import { highlightingFor, HighlightStyle, syntaxHighlighting, syntaxTree } from "@codemirror/language";
import { FOLD_MARKER, sanitize, TextManager } from "../text";
import { getStyleTags, tags } from "@lezer/highlight";
import { EditorView } from "codemirror";
import { Decoration, keymap, ViewPlugin, ViewUpdate, WidgetType } from "@codemirror/view";
import { EditorSelection, Prec, RangeSet, StateEffect, StateField } from "@codemirror/state";
import { findSoruceMappedPreviousElement } from "./syncDualPane";
import { getLineById } from "../markdown/markdownSourceMap";
import { reviewKey } from "../markdown/markdownReview";
import { getReviewItems, getSuggestions, reviewCardPosition, setReviewStateEffect } from "./review";
import { reviewState } from "./reviewStateField";

export const inlinePreview = (/** @type {TextManager} */ text, options, editorView) => {
  const previewFont = "Lato";
  const baseFont = { fontFamily: previewFont, lineHeight: "1.3em" };
  const baseHeading = { fontWeight: "bold", lineHeight: 1.5, fontFamily: previewFont };
  const markdownHighlightStyle = HighlightStyle.define([
    { tag: tags.heading1, ...baseHeading, fontSize: "1.8em" },
    { tag: tags.heading2, ...baseHeading, fontSize: "1.5em" },
    { tag: tags.heading3, ...baseHeading, fontSize: "1.25em" },
    { tag: tags.heading4, ...baseHeading, fontSize: "1.15em" },
    { tag: [tags.link, tags.url], ...baseFont, textDecoration: "underline", color: "var(--accent-dark)" },
    { tag: tags.macroName, ...baseFont, color: "var(--accent-dark)" },
    { tag: tags.emphasis, ...baseFont, fontStyle: "italic" },
    { tag: tags.strong, ...baseFont, fontWeight: "bold" },
    { tag: tags.strikethrough, ...baseFont, textDecoration: "line-through" },
    { tag: [tags.monospace, tags.atom], ...baseFont, fontFamily: "monospace" },
    { tag: [tags.content], ...baseFont },
    { tag: tags.meta, color: "darkgrey" },
  ]);
  // CodeMirror probes the logical line start during vertical cursor movement. Keep source list markers and indentation measurable;
  // using display: none here makes ArrowUp skip consecutive decorated lines.
  const markdownTheme = EditorView.theme({
    "&": { fontSize: "16px" },
    ".cm-inline-bullet, .cm-inline-ordered-list-marker": { display: "inline-grid" },
    ".cm-inline-bullet > *, .cm-inline-ordered-list-marker > *": { visibility: "hidden", gridArea: "1 / 1" },
    ".cm-inline-bullet::after, .cm-inline-ordered-list-marker::after": { gridArea: "1 / 1" },
    ".cm-inline-indent": { display: "inline-block" },
    ".cm-inline-indent *": { visibility: "hidden" },
    ":is(.cm-widgetBuffer:has(+ .inline-custom-styles), .inline-custom-styles + .cm-widgetBuffer)": { display: "none" },
    ".cm-critic-meta": { display: "none" },
    // Shrink-to-fit so that the rest of the line stays clickable - that is how you get to the source
    // of a disclosure widget whose summary handles its own clicks.
    ".cm-inline-rendered-md details": { display: "inline-block", verticalAlign: "top", maxWidth: "calc(100% - 2ch)" },
    ".cm-error:has(.tok-heading)": { textDecoration: "none" },
    ".cm-error .tok-heading": { textDecoration: "spelling-error" },
    ".suggestions-insert:has(.tok-heading)": { textDecoration: "none" },
    ".suggestions-insert .tok-heading": { textDecoration: "underline 2px var(--green-500)", textDecorationThickness: "2px" },
    ".suggestions-delete:has(.tok-heading)": { textDecoration: "none" },
    ".suggestions-delete .tok-heading": { textDecoration: "line-through 3px red" },
  });

  const tokenElement = ["InlineCode", "Emphasis", "StrongEmphasis", "Strikethrough", "FencedCode", "Image", "Blockquote"];
  const decorationHidden = Decoration.replace({});
  const decorationMonospace = Decoration.mark({ class: "cm-inline-mono" });
  let suggestionState;
  let currentSuggestionRanges = [];
  const suggestionRanges = (state) => {
    if (state !== suggestionState) {
      suggestionState = state;
      currentSuggestionRanges = options.collaboration.peek().commentsEnabled
        ? [...getSuggestions(state).values()].flatMap(({ anchors }) => anchors).filter(({ from, to }) => from < to)
        : [];
    }
    return currentSuggestionRanges;
  };
  const nodeInSuggestion = (state, node) => suggestionRanges(state).some((range) => node.from >= range.from && node.to <= range.to);
  const nodeInSelection = (state, node) =>
    editorView.peek()?.hasFocus &&
    state.selection.ranges.some((r) => {
      const rFrom = state.doc.lineAt(r.from).number;
      const rTo = state.doc.lineAt(r.to).number;
      const nodeFrom = state.doc.lineAt(node.from).number;
      const nodeTo = state.doc.lineAt(node.to).number;
      return (rFrom >= nodeFrom && rFrom <= nodeTo) || (rTo >= nodeFrom && rTo <= nodeTo) || (nodeFrom >= rFrom && nodeTo <= rTo);
    });
  const nodeInMonospace = (...args) => nodeInSelection(...args) || nodeInSuggestion(...args);
  const renderedBlockNodes = ["Table", "Blockquote", "FencedCode", "Image", "Checkbox", "HTMLBlock"];

  const moveCursorVertically = (forward) => (view) => {
    const moveRange = (range) => {
      if (!range.empty) return EditorSelection.cursor(forward ? range.to : range.from);

      let moved = view.moveVertically(range, forward);
      if (moved.head == range.head) moved = view.moveToLineBoundary(range, forward);

      // A rendered block is a single replacement widget. CodeMirror cannot map a
      // vertical position inside that widget back to its source, and may return
      // the far boundary of the range. Enter it at the boundary nearest to the
      // cursor instead, which also reveals the source for further movement.
      let boundary = null;
      if (forward ? moved.head > range.head : moved.head < range.head) {
        syntaxTree(view.state).iterate({
          from: Math.min(range.head, moved.head),
          to: Math.max(range.head, moved.head),
          enter(node) {
            if (!renderedBlockNodes.includes(node.name) || nodeInMonospace(view.state, node)) return;

            const crossed = forward ? range.head <= node.from && moved.head >= node.to : range.head >= node.to && moved.head <= node.from;
            if (!crossed) return;

            const candidate = forward ? node.from : node.to;
            if (boundary == null || (forward ? candidate < boundary : candidate > boundary)) boundary = candidate;
          },
        });
      }

      return boundary == null ? moved : EditorSelection.cursor(boundary, forward ? 1 : -1, undefined, moved.goalColumn);
    };

    const selection = EditorSelection.create(view.state.selection.ranges.map(moveRange), view.state.selection.mainIndex);
    if (selection.eq(view.state.selection, true)) return false;
    view.dispatch({ selection, scrollIntoView: true, userEvent: "select" });
    return true;
  };

  const focusEffect = StateEffect.define();

  const renderedInlineNodes = ["Link", "URL", "InlineCode", "Role", "Transform"];
  // CodeMirror hides widgets inside replaced ranges, so keep review cards at the rendered node's boundary.
  const mapReviewCardPosition = (state, position) => {
    let mappedPosition = position;
    for (let node = syntaxTree(state).resolveInner(position, -1); node; node = node.parent) {
      if ((renderedBlockNodes.includes(node.name) || renderedInlineNodes.includes(node.name)) && !nodeInSelection(state, node)) {
        mappedPosition = node.to;
      }
    }
    return mappedPosition;
  };
  class RenderedMarkdownWidget extends WidgetType {
    constructor(src, isBlock, start, end, sourceOffset, reviewItems, cssClasses = []) {
      super();
      this.src = src;
      this.isBlock = isBlock;
      this.start = start;
      this.end = end;
      this.md = text.md.peek();
      this.sourceOffset = sourceOffset; // The Markdown renderer only sees fragment, while review anchors use full-document positions.
      this.reviewItems = reviewItems;
      this.reviewKey = reviewKey(reviewItems);
      this.cssClasses = cssClasses;
    }

    eq(widget) {
      return this.src === widget.src && this.reviewKey === widget.reviewKey && this.md === widget.md;
    }

    toDOM() {
      const content = document.createElement("span");
      content.className = "cm-inline-rendered-md";
      if (this.cssClasses.length > 0) {
        content.classList.add("inline-custom-styles");
      }
      this.cssClasses.flatMap((c) => c.split(" ")).forEach((c) => content.classList.add(c));
      for (let l = this.start; l <= this.end; l++) {
        text.lineMap.delete(l);
      }

      const env = {
        lineMap: text.lineMap,
        startLine: this.start,
        chunkId: 0,
        sourceOffset: this.sourceOffset,
        reviewItems: this.reviewItems,
      };
      const render = (src) => (this.isBlock ? this.md.render(src, env) : this.md.renderInline(src, env));
      content.innerHTML = sanitize(render(this.src));
      return content;
    }

    ignoreEvent(ev) {
      // Elements with an activation behavior of their own are left to the browser - the
      // `preventDefault` in the mousedown handler below would otherwise swallow it.
      return ev.type == "mousedown" && (options.onPreviewClick.peek()?.(ev) || ev.target.closest?.("a, summary") != null);
    }
  }

  function replaceMd(state) {
    const decorations = [];

    syntaxTree(state).iterate({
      enter(node) {
        const isBlock = renderedBlockNodes.includes(node.name);
        if (!isBlock && !renderedInlineNodes.includes(node.name)) return;
        if (nodeInMonospace(state, node)) return false;

        const lineFrom = state.doc.lineAt(node.from);
        const lineTo = state.doc.lineAt(node.to);
        const isMultiline = isBlock && lineTo.number > lineFrom.number;
        const fromOffset = node.from - lineFrom.from;
        let src = state.doc.sliceString(node.from, node.to);
        if (isMultiline && fromOffset > 0) {
          src = src
            .split("\n")
            .map((line, i) => (i == 0 ? line : line.slice(fromOffset)))
            .join("\n");
        }
        const parent = node.node.parent.toTree();
        const tags = getStyleTags(parent)?.tags;
        const parentClass = parent.type.name.startsWith("ATXHeading") && tags ? highlightingFor(state, tags) : null;
        const reviewItems = options.collaboration.peek().commentsEnabled
          ? [...getReviewItems(state).values()].filter(({ anchors }) => anchors.some(({ from, to }) => from < node.to && to > node.from))
          : [];

        const sourceOffset = node.from;
        const decoration = Decoration.replace({
          widget: new RenderedMarkdownWidget(
            src,
            isBlock,
            lineFrom.number,
            lineTo.number,
            sourceOffset,
            reviewItems,
            parentClass ? [parentClass] : [],
          ),
        });

        decorations.push(decoration.range(node.from, node.to));
      },
    });

    return decorations;
  }

  const renderMdInline = () => {
    let initialUpdate = true;
    return StateField.define({
      create(state) {
        return RangeSet.of(replaceMd(state), true);
      },

      update(curr, transaction) {
        const focusChanged = transaction.effects.some((e) => e.is(focusEffect));
        const reviewsChanged = transaction.effects.some((effect) => effect.is(setReviewStateEffect));
        const selectionChanged =
          transaction.startState.doc.lineAt(transaction.startState.selection.main.head).number !==
          transaction.state.doc.lineAt(transaction.state.selection.main.head).number;
        if (!initialUpdate && !focusChanged && !reviewsChanged && !transaction.docChanged && !selectionChanged && !transaction.reconfigured)
          return curr;
        if (initialUpdate) initialUpdate = false;
        return RangeSet.of(replaceMd(transaction.state), true);
      },

      provide(field) {
        return EditorView.decorations.from(field);
      },
    });
  };

  const renderedMarkdown = renderMdInline();
  const previewPlugin = ViewPlugin.fromClass(
    class {
      constructor(view) {
        this.decorations = this.process(view);
      }

      update(/** @type {ViewUpdate} */ update) {
        if (update.docChanged || update.viewportChanged || update.selectionSet || update.focusChanged) this.decorations = this.process(update.view);
      }

      process(/** @type {EditorView} */ view) {
        const widgets = [];

        for (const { from, to } of view.visibleRanges) {
          syntaxTree(view.state).iterate({
            from,
            to,
            enter(node) {
              if (node.name.startsWith("ATXHeading") && nodeInMonospace(view.state, node)) return false;

              if (node.name.startsWith("ATXHeading") && options.collapsibleHeadingMarker.value) {
                const line = view.state.doc.lineAt(node.from);
                if (FOLD_MARKER.test(line.text)) widgets.push(decorationHidden.range(line.from + line.text.lastIndexOf("(^)"), line.to));
              }
              const elementToken = node.name.startsWith("SetextHeading") || tokenElement.includes(node.name);
              if ((elementToken && nodeInMonospace(view.state, node)) || node.name == "Frontmatter") {
                const startLine = view.state.doc.lineAt(node.from);
                const endLine = view.state.doc.lineAt(node.to);
                widgets.push(decorationMonospace.range(startLine.from, endLine.to));
                return false;
              }

              if (node.name === "ListMark" && node.matchContext(["BulletList", "ListItem"]) && !nodeInMonospace(view.state, node)) {
                widgets.push(
                  Decoration.mark({
                    class: "cm-inline-bullet",
                  }).range(node.from, node.to),
                );
              }

              if (node.name === "ListMark" && node.matchContext(["OrderedList", "ListItem"]) && !nodeInMonospace(view.state, node)) {
                // Get what list item number should this one have, this is to keep it consistent with standard markdown-it rendering
                const marks = node.node.parent.parent.getChildren("ListItem").flatMap((i) => i.getChildren("ListMark"));
                const base = parseInt(view.state.doc.sliceString(marks[0].from, marks[0].to));
                const num = marks.findIndex((m) => m.from == node.from) + base;
                widgets.push(
                  Decoration.mark({ class: "cm-inline-ordered-list-marker", attributes: { "data-item-num": `${num}.` } }).range(node.from, node.to),
                );
              }

              if (node.name === "HeaderMark") {
                const parent = node.node.parent.type.name;
                // Hide the space between the HeaderMark and text in ATX headings
                const to = parent.startsWith("ATX") ? node.to + 1 : node.to;
                const line = view.state.doc.lineAt(node.from);
                const headingText = line.text.slice(node.to - line.from).trim();
                if (parent.startsWith("ATX") && headingText.length == 0) {
                  console.warn(`Empty heading in inline mode, not rendering(line ${line.number}): "${line.text}"`);
                } else {
                  widgets.push(decorationHidden.range(node.from, to));
                }
              }

              if ((node.name == "EmphasisMark" || node.name == "StrikethroughMark") && !nodeInMonospace(view.state, node)) {
                widgets.push(decorationHidden.range(node.from, node.to));
              }

              if (node.name == "HardBreak" && !nodeInMonospace(view.state, node)) {
                widgets.push(decorationHidden.range(node.from, node.from + 1));
              }
            },
          });
        }

        if (editorView.peek()?.hasFocus) {
          view.state.selection.ranges.forEach((r) => {
            const startLine = view.state.doc.lineAt(r.from);
            const endLine = view.state.doc.lineAt(r.to);
            if (startLine.from != endLine.to) {
              widgets.push(decorationMonospace.range(startLine.from, endLine.to));
            }
          });

          suggestionRanges(view.state)
            .filter((range) => nodeInSelection(view.state, range))
            .forEach((range) => widgets.push(decorationMonospace.range(range.from, range.to)));
        }

        // Make all indenting same width as monospace text indent
        const selectionLines = editorView.peek()?.hasFocus
          ? new Set(
              view.state.selection.ranges.flatMap((r) => {
                const startLine = view.state.doc.lineAt(r.from).number;
                const endLine = view.state.doc.lineAt(r.to).number;
                return Array.from({ length: endLine - startLine + 1 }, (_, i) => i + startLine);
              }),
            )
          : new Set();
        for (const range of view.visibleRanges) {
          const start = view.state.doc.lineAt(range.from).number;
          const end = view.state.doc.lineAt(range.to).number;
          for (let i = start; i <= end; i++) {
            if (selectionLines.has(i)) continue;
            const line = view.state.doc.line(i);
            const indentLength = line.text.length - line.text.trimStart().length;
            // Empty line or no indent
            if (indentLength == line.text.length || indentLength == 0) continue;

            const monoCharWidth = 8.43333;
            widgets.push(
              Decoration.mark({ class: "cm-inline-indent", attributes: { style: `width: ${indentLength * monoCharWidth}px;` } }).range(
                line.from,
                line.from + indentLength,
              ),
            );
          }
        }

        widgets.sort((w1, w2) => w1.from - w2.from);

        return Decoration.set(widgets);
      }
    },
    {
      provide: () => [
        syntaxHighlighting(markdownHighlightStyle),
        markdownTheme,
        renderedMarkdown,
        Prec.high(
          keymap.of([
            { key: "ArrowUp", run: moveCursorVertically(false), preventDefault: true },
            { key: "ArrowDown", run: moveCursorVertically(true), preventDefault: true },
          ]),
        ),
        EditorView.focusChangeEffect.of((_, focus) => focusEffect.of(focus)),
      ],
      decorations: (v) => v.decorations,
      eventHandlers: {
        mousedown(ev, view) {
          if (!(ev.target instanceof Element) || !ev.target.matches(".cm-inline-rendered-md *")) return;

          ev.preventDefault();
          if (ev.target.tagName == "INPUT") {
            // Toggle checkbox
            const line = view.state.doc.lineAt(view.posAtDOM(ev.target));
            const statusIdx = line.text.indexOf("[") + 1;
            const from = line.from + statusIdx;
            const to = from + 1;
            const current = line.text.slice(statusIdx, statusIdx + 1);
            const newStatus = current == " " ? "x" : " ";
            view.dispatch({ changes: { from, to, insert: newStatus } });
          } else {
            view.focus();
            let id = ev.target.getAttribute("data-line-id");
            let elem = ev.target;
            if (!id) {
              // check parents and siblings
              while (elem && elem.tagName !== "HTML-CHUNK") {
                const parent = elem.parentElement;
                [id, elem] = findSoruceMappedPreviousElement(elem);
                if (id) break;
                elem = parent;
              }
            }
            if (id) {
              const lineNumber = getLineById(text.lineMap, id);
              const line = view.state.doc.line(lineNumber);
              view.dispatch({ selection: { anchor: line.from } });
            } else {
              view.dispatch({ selection: { anchor: view.posAtDOM(ev.target) } });
            }
          }
        },
      },
    },
  );

  // Card positions follow inline rendering and selection even when the reviews themselves are unchanged.
  const cardPosition = reviewCardPosition.compute([renderedMarkdown, "selection"], (state) =>
    options.collaboration.peek().commentsEnabled && state.field(reviewState, false)?.reviewItems.size
      ? (state, position) => mapReviewCardPosition(state, position)
      : mapReviewCardPosition,
  );
  return [cardPosition, previewPlugin];
};
